<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class Order extends Model {use SoftDeletes;protected $fillable=['order_number','customer_id','created_by','status','payment_status','delivery_status','subtotal','discount_amount','tax_amount','total_amount','delivery_address','order_date','delivered_date','notes'];protected $casts=['order_date'=>'date','delivered_date'=>'date','subtotal'=>'decimal:2','discount_amount'=>'decimal:2','tax_amount'=>'decimal:2','total_amount'=>'decimal:2'];public function customer(){return $this->belongsTo(Customer::class);}public function creator(){return $this->belongsTo(User::class,'created_by');}public function items(){return $this->hasMany(OrderItem::class);}public function payments(){return $this->hasMany(Payment::class);}}
